// Bundle the Composio catalog + library guides into a JS module so serverless
// hosts (Vercel) ship them with the code. Run after build-library / editorial.
import fs from 'node:fs';
import path from 'node:path';
import { ROOT } from '../lib/env.js';

const dataDir = path.join(ROOT, 'data');
const catalog = JSON.parse(fs.readFileSync(path.join(dataDir, 'composio-oauth-toolkits.json'), 'utf8'));
const library = {};
for (const f of fs.readdirSync(path.join(dataDir, 'guides')).filter((x) => x.endsWith('.json')).sort()) {
  library[f.slice(0, -5)] = JSON.parse(fs.readFileSync(path.join(dataDir, 'guides', f), 'utf8'));
}
const indexHtml = fs.readFileSync(path.join(ROOT, 'public', 'index.html'), 'utf8');
const out = `// GENERATED by scripts/bundle-data.js. Do not edit; edit data/ and re-run.\nexport const catalog = ${JSON.stringify(catalog)};\nexport const library = ${JSON.stringify(library)};\nexport const indexHtml = ${JSON.stringify(indexHtml)};\n`;
fs.writeFileSync(path.join(ROOT, 'lib', 'data.generated.js'), out);
console.log(`bundled ${catalog.length} catalog entries and ${Object.keys(library).length} guides (${Math.round(out.length / 1024)} KB)`);
